INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sk-b2g-2023', id, '2023-04-01', 1, 'https://www.financnasprava.sk/en/homepage' FROM countries WHERE name_en = 'Slovakia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-b2g-2023', 'en', 'B2G/G2G e-invoicing mandatory via IS EFA', 'Slovakia introduces mandatory structured e-invoicing for business-to-government and government-to-government transactions through the IS EFA (Informačný Systém Elektronickej Fakturácie) platform, aligned with EN 16931 — the foundation the 2027 B2B mandate extends.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sk-b2b-postponed-2024', id, '2024-01-01', 1, 'https://www.financnasprava.sk/en/homepage' FROM countries WHERE name_en = 'Slovakia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-b2b-postponed-2024', 'en', 'Earlier voluntary B2B plan quietly postponed', 'A voluntary B2B framework originally planned for January 2022 was postponed indefinitely, reflecting the genuine complexity of getting this right — worth remembering when reading today''s confirmed dates.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sk-peppol-codelist-2025', id, '2025-12-23', 1, 'https://www.financnasprava.sk/en/homepage' FROM countries WHERE name_en = 'Slovakia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-peppol-codelist-2025', 'en', 'Peppol Code Lists v9.5 defines Slovak identifier scheme', 'Scheme 0245 (SG:DIC) is formalised for the 10-digit Slovak Tax Identification Number (DIČ), the identifier Slovak end users will register under on the Peppol network.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sk-voluntary', id, '2026-05-01', 0, 'https://www.financnasprava.sk/en/homepage' FROM countries WHERE name_en = 'Slovakia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-voluntary', 'en', 'Voluntary e-invoicing / e-reporting transition period begins', 'Businesses can voluntarily register to test structured e-invoicing and reporting ahead of the January 2027 mandate, using a decentralised Peppol-based "5-corner" model.', '["Register for voluntary participation with the Financial Administration to test integrations early", "Confirm your accounting software can generate Peppol BIS 3.0 UBL XML"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sk-mandate', id, '2027-01-01', 0, 'https://www.financnasprava.sk/en/homepage' FROM countries WHERE name_en = 'Slovakia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-mandate', 'en', 'Mandatory domestic B2B/B2G e-invoicing and near-real-time reporting', 'Structured e-invoicing and real-time reporting become mandatory for domestic B2B and B2G transactions between Slovak VAT taxpayers, using certified "Digital Postman" access points on a Peppol-based network.', '["Select an approved Digital Postman (certified access point) provider", "From 2027, input VAT deductions cannot be claimed on non-compliant incoming invoices", "Note: cross-border e-invoicing follows later, under the EU ViDA timeline from July 2030"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sk-postman-mandatory-2027', id, '2027-07-01', 1, 'https://www.financnasprava.sk/en/homepage' FROM countries WHERE name_en = 'Slovakia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-postman-mandatory-2027', 'en', 'Certified Digital Postman transmission becomes mandatory', 'Using only certified Digital Postman service providers for transmission and reception becomes a firm requirement — the educational grace period built into the first half of 2027 ends here.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sk-crossborder-2030', id, '2030-07-01', 1, 'https://www.financnasprava.sk/en/homepage' FROM countries WHERE name_en = 'Slovakia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sk-crossborder-2030', 'en', 'Cross-border extension; legacy reporting phased out', 'The mandate extends to intra-EU B2B transactions and foreign entities with Slovak VAT registrations. The domestic "Kontrolný výkaz" (VAT control statement) and EU "súhrnný výkaz" (EC Sales List) are fully retired, and the invoice issuance deadline shortens from 15 to 10 days.', '[]');
